const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    // Approximate a region within the Dry Chaco (Gran Chaco ecoregion)
    // This polygon covers a significant portion of the Dry Chaco in Argentina and Paraguay.
    const dryChaco = ee.Geometry.Polygon(
      [[[-65.0, -19.0],
        [-57.0, -19.0],
        [-57.0, -32.0],
        [-65.0, -32.0],
        [-65.0, -19.0]]]
    );

    const scale = 1000; // Resolution for reduction, in meters. 1km to avoid timeouts.

    // 2. Data Acquisition
    const gfc = ee.Image('UMD/hansen/global_forest_change_2023_v1_11');

    // Define forest as areas with > 10% tree cover in 2000.
    const treeCoverThreshold = 10; // Percent

    // Forest area in 2000
    const forest2000 = gfc.select('treecover2000').gt(treeCoverThreshold);

    // Forest area in 2019
    // Forest in 2019 = forest in 2000 AND not lost by 2019
    // lossyear band is 1-19 for loss during 2001-2019, 0 for no loss.
    // So, lossyear > 0 AND lossyear <= 19 means loss occurred by end of 2019.
    const forestLossBy2019 = gfc.select('lossyear').gt(0).and(gfc.select('lossyear').lte(19));
    const forest2019 = forest2000.and(forestLossBy2019.not()); // Not lost by 2019

    // Calculate initial pixel counts for validation
    const reducer = ee.Reducer.sum(); // Sum of 1s (forest pixels) for area calculation

    // Area in 2000
    const area2000 = forest2000.multiply(ee.Image.pixelArea()); // Convert to sq meters
    const forestArea2000 = area2000.reduceRegion({
      reducer: reducer,
      geometry: dryChaco,
      scale: scale,
      maxPixels: 1e9
    }).get('treecover2000');

    // Area in 2019
    const area2019 = forest2019.multiply(ee.Image.pixelArea()); // Convert to sq meters
    const forestArea2019 = area2019.reduceRegion({
      reducer: reducer,
      geometry: dryChaco,
      scale: scale,
      maxPixels: 1e9
    }).get('treecover2000');

    const initialForestArea2000 = await forestArea2000.getInfo();
    const currentForestArea2019 = await forestArea2019.getInfo();

    if (initialForestArea2000 === null || currentForestArea2019 === null) {
      console.log("C3: Calculation Failure. One or both area calculations resulted in None.");
      return;
    }

    if (initialForestArea2000 === 0) {
        console.log("No valid forest pixels found in 2000 for the specified threshold and region.");
        console.log("C2");
        return;
    }

    // Convert area from sq meters to sq km for readability
    const initialForestAreaKm2 = initialForestArea2000 / 1e6;
    const currentForestAreaKm2 = currentForestArea2019 / 1e6;

    // 4. Calculation
    const percentageDecrease = ((initialForestAreaKm2 - currentForestAreaKm2) / initialForestAreaKm2) * 100;

    // 5. Validation & Final Answer
    console.log(`Forest Area 2000: ${initialForestAreaKm2.toFixed(2)} km²`);
    console.log(`Forest Area 2019: ${currentForestAreaKm2.toFixed(2)} km²`);
    console.log(`Percentage Decrease: ${percentageDecrease.toFixed(2)}%`);

    if (isNaN(percentageDecrease)) {
        console.log("C3: Calculation Failure. Percentage decrease is NaN.");
    } else if (percentageDecrease > 10) {
      console.log("A"); // Yes
    } else {
      console.log("B"); // No
    }

  } catch (error) {
    console.error("An error occurred:", error);
    console.log("D"); // General error
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
